const registry=JSON.parse(fs.readFileSync(R+'/working-identity-registry.json'));
const mapText=fs.readFileSync(P+'/ledger/area-map-whole-system-architecture.md','utf8');
const maps=[...mapText.matchAll(/^\| `(docs\/[^`]+)` \| `(docs\/[^`]+)` \| ([^|]+) \| ([^|]+) \| (.+)\|$/gm)].map(m=>({source:m[1],target:m[2],kind:m[3].trim()}));
const sources=Object.fromEntries(maps.map(m=>[m.source,git('show',head+':'+m.source)]));
