for(const p of scanPaths){let text;try{text=fs.readFileSync(p,'utf8')}catch{continue};text.split(/\r?\n/).forEach((line,i)=>{for(const m of maps){if(line.includes(m.source)||line.includes(path.posix.basename(m.source))&&line.includes('](')){refs[m.source].push({path:p,line:i+1,text:line})}}})}
const live={version:1,sourceCommit:head,authorSession:author,scanBeforeCarriage:true,scanPaths:scanPaths.length,limitations:'Literal source-path/basename references plus source subject reading; this is relevance evidence, not a code truth scan. Immutable plans/archive/history and .fgos are excluded. No retirement is inferred from a missing text reference.',files:maps.map(m=>({source:m.source,target:m.target,sourceBlob:immutable[m.source],references:refs[m.source],sections:extract(sources[m.source]).filter(u=>u.unitKind==='heading').map(u=>({anchor:u.anchor,title:u.title,sourceUnitDigest:u.textDigest,liveFileReferences:refs[m.source].length,sectionReferences:refs[m.source].filter(r=>r.text.includes('#'+u.anchor)),classification:/retired|lịch sử quyết định/i.test(u.title)?'Explicitly dated decision narrative; preserve inside the mapped architecture/spec carrier, no truth or retirement inference.':'Current architecture intent/navigation/spec or explicitly proposed roadmap; preserve scope and implementation qualifications verbatim, no truth claim.',retirement:'none: no evidence that this whole-system source section is an unreferenced retired subject'}))}))};
json(R+'/liveness-whole-system-architecture.json',live);
const baselineBlobs=new Map(fs.readFileSync(R+'/source-blobs.txt','utf8').trim().split('\n').map(s=>s.split(' ')));
const planB=['docs/specs/system-overview.md','docs/platform/component-boundary.md'].map(p=>({path:p,baselineBlob:baselineBlobs.get(p),lastSync:prev,lastSyncBlob:git('rev-parse',prev+':'+p).trim(),currentSync:head,currentBlob:git('rev-parse',head+':'+p).trim()}));
